#include <cstdio>
#include <cstdint>
#include <cstring>
#include <vector>
#include "fuzzer/FuzzedDataProvider.h"

extern "C" {
#include "usbredirparser.h"
}

static FuzzedDataProvider *fdp;

static int parser_read(void *priv, uint8_t *data, int count)
{
    return fdp->ConsumeData(data, count);
}

static int parser_write(void *priv, uint8_t *data, int count)
{
    return count;
}

static void parser_hello(void *priv, struct usb_redir_hello_header *h)
{
    fprintf(stderr, "[dbg] hello\n");
}

static void parser_device_disconnect(void *priv, struct usb_redir_device_disconnect_header *h)
{
    fprintf(stderr, "[dbg] device_disconnect\n");
}

static void parser_device_disconnect_ack(void *priv)
{
    fprintf(stderr, "[dbg] device_disconnect_ack\n");
}

static void parser_filter_reject(void *priv, struct usb_redir_filter_reject_header *h)
{
}

static void parser_filter_filter(void *priv, struct usbredirfilter_rule *rules, int rules_count)
{
}

static void parser_unknown(void *priv, uint8_t type, uint8_t *data, int data_len)
{
}

static int try_unserialize(struct usbredirparser *parser, FuzzedDataProvider *fdp)
{
    size_t len = fdp->ConsumeIntegralInRange<size_t>(1, 64 * 1024);
    std::vector<uint8_t> state;
    state.reserve(len);
    if (len >= 4) {
        state.insert(state.end(), {'U', 'R', 'P', '1'});
        len -= 4;
    }
    if (len > 0) {
        const std::vector<uint8_t> payload{fdp->ConsumeBytes<uint8_t>(len)};
        state.insert(state.end(), payload.cbegin(), payload.cend());
    }
    fprintf(stderr, "[dbg] unserialize state size=%zu\n", state.size());
    return usbredirparser_unserialize(parser, state.data(), state.size());
}

static int try_serialize(struct usbredirparser *parser, FuzzedDataProvider *fdp)
{
    uint8_t *state = NULL;
    size_t len = 0;
    int ret = usbredirparser_serialize(parser, &state, &len);
    fprintf(stderr, "[dbg] serialize ret=%d len=%zu\n", ret, len);
    free(state);
    return ret;
}

extern "C" int LLVMFuzzerTestOneInput(const uint8_t *data, size_t size)
{
    fdp = new FuzzedDataProvider(data, size);

    uint32_t caps[USB_REDIR_CAPS_SIZE];
    for (size_t i = 0; i < USB_REDIR_CAPS_SIZE; i++) {
        caps[i] = fdp->ConsumeIntegral<uint32_t>();
    }

    uint8_t init_flags = fdp->ConsumeIntegral<uint8_t>() &
        (usbredirparser_fl_usb_host | usbredirparser_fl_no_hello);

    struct usbredirparser *parser = usbredirparser_create();
    if (!parser) {
        delete fdp;
        return 0;
    }

    usbredirparser_init(parser, "fuzzer", "fuzzer", caps, USB_REDIR_CAPS_SIZE, init_flags);

    usbredirparser_set_callbacks(parser, parser_read, parser_write, parser_hello,
                                 parser_device_disconnect, parser_device_disconnect_ack,
                                 parser_filter_reject, parser_filter_filter, parser_unknown, NULL);

    if (fdp->ConsumeBool() && try_unserialize(parser, fdp) != 0) {
        fprintf(stderr, "[dbg] unserialize failed\n");
        goto out;
    }

    while (fdp->remaining_bytes() > 0 || usbredirparser_has_data_to_write(parser)) {
        fprintf(stderr, "[dbg] loop top remaining=%zu has_write=%d\n", fdp->remaining_bytes(), usbredirparser_has_data_to_write(parser));
        if (fdp->ConsumeBool() && try_serialize(parser, fdp) != 0) {
            fprintf(stderr, "[dbg] serialize1 failed\n");
            goto out;
        }
        if (fdp->remaining_bytes() > 0) {
            int ret = usbredirparser_do_read(parser);
            fprintf(stderr, "[dbg] do_read ret=%d remaining=%zu\n", ret, fdp->remaining_bytes());
            switch (ret) {
            case usbredirparser_read_parse_error:
                break;
            default:
                goto out;
            }
            if (fdp->ConsumeBool() && try_serialize(parser, fdp) != 0) {
                fprintf(stderr, "[dbg] serialize2 failed\n");
                goto out;
            }
        }
        while (usbredirparser_has_data_to_write(parser)) {
            int ret = usbredirparser_do_write(parser);
            fprintf(stderr, "[dbg] do_write ret=%d\n", ret);
            if (ret < 0) {
                goto out;
            }
        }
    }

out:
    usbredirparser_destroy(parser);
    delete fdp;
    return 0;
}
